package com.example.billingservice.service;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;@Component public class DependencyClient{private final RestClient client=RestClient.create();private final String network,fulfillment;public DependencyClient(@Value("${services.network-url}")String n,@Value("${services.fulfillment-url}")String f){network=n;fulfillment=f;}public String activationStatus(String order){return status(network+"/api/activations?orderId="+order);}public String fulfillmentStatus(String order){return status(fulfillment+"/api/fulfillments?orderId="+order);}private String status(String url){try{return client.get().uri(url).retrieve().body(StatusResponse.class).status();}catch(Exception e){return "UNAVAILABLE";}}private record StatusResponse(String status){}}
